// src/components/MovieSearchBar.js

import React, { useState } from 'react';
import { searchMovies } from '../api/movieApi';

function MovieSearchBar({ onMovieSelect }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;
    const movies = await searchMovies(query);
    setResults(movies.slice(0, 5));
  };

  const handleSelectMovie = (movie) => {
    onMovieSelect(movie);
    setQuery('');
    setResults([]);
  };

  return (
    <div className="movie-search-bar">
      {/* ⭐️ form 태그로 감싸서 Enter 키로도 검색이 되도록 개선 */}
      <form onSubmit={handleSearch} className="search-input-group">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="관람한 영화를 검색하세요"
        />
        {/* ⭐️ 버튼에 className 추가 */}
        <button type="submit" className="search-button">검색</button>
      </form>
      {results.length > 0 && (
        <ul className="search-results-list">
          {results.map((movie) => (
            <li key={movie.movieCd} onClick={() => handleSelectMovie(movie)}>
              {movie.movieNm} ({movie.openDt?.substring(0, 4)})
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default MovieSearchBar;
